head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[$p > M > top]<br/>최상위 페이지의 Scope 객체를 반환합니다.",
    "validation" : [
        "최상위 페이지의 Scope 객체 또는 Window 객체를 반환해야 합니다.",
        "팝업 유형이 'browserPopup' 인 경우 별도의 Window 객체에 팝업이 생성되므로, 팝업의 최상위 페이지 Scope 객체가 반환되어야 합니다.",
        "반환된 Scope 객체를 통해 최상위 화면에 정의된 컴포넌트와 scwin 객체에 접근할 수 있어야 합니다.",
    ]
}


// 최상위 화면의 scwin 함수 (top() 반환 Scope 를 통해 호출됨)
scwin.getTopPageInfo = function () {
    return "최상위 페이지 scwin.getTopPageInfo() 호출 성공";
};



scwin.onpageload = function () {
    $c.gcm.createCommonDatalist();
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



scwin.btn_top_main_onclick = function () {
    var topScope = $p.top();

    wf_body_bottom.getObj("scwin").setReturnValue("메인 $p.top() 반환 타입 : " + (typeof topScope));
    wf_body_bottom.getObj("scwin").setReturnValue("메인 $p.top() === window 여부 : " + (topScope === window));
    wf_body_bottom.getObj("scwin").setReturnValue("메인 $p.top().scwin 존재 여부 : " + (typeof topScope.scwin !== 'undefined'));
}



scwin.btn_top_wframe_onclick = function () {
    var topScope = wf_mid.getObj("$p").top();

    // 최상위 화면의 InputBox 에 값 설정
    topScope.ibx_top.setValue("Example");

    // 최상위 화면의 scwin 함수 호출
    var rtn = topScope.scwin.getTopPageInfo();

    wf_body_bottom.getObj("scwin").setReturnValue("wf_mid 내부 $p.top() 반환 타입 : " + (typeof topScope));
    wf_body_bottom.getObj("scwin").setReturnValue("  ibx_top.setValue('Example') 후 getValue() : '" + topScope.ibx_top.getValue() + "'");
    wf_body_bottom.getObj("scwin").setReturnValue("  scwin.getTopPageInfo() : " + rtn);
}



scwin.btn_openBrowserPopup_onclick = function () {
    var options = {
        id: "top_browserPopup",
        type: "browserPopup",
        width: "500px",
        height: "250px",
        top: "100px",
        left: "100px",
        popupName: "top browserPopup 테스트",
        modal: false
    };

    $p.openPopup("/sample/common_link/$p_top_popup.xml", options);
    wf_body_bottom.getObj("scwin").setReturnValue("openPopup 실행 (browserPopup)");
    wf_body_bottom.getObj("scwin").setReturnValue("팝업 내부에서 $p.top() 결과(팝업 최상위 Scope)를 확인하세요.");
}
